def _scanline_intersections(contours, y):
    """Find all X intersections of a horizontal line at y with polygon contours.

    Uses the same edge-crossing math as _point_in_polygon in svg_engine.py,
    but collects intersection X values instead of toggling inside/outside.
    """
    intersections = []
    for contour in contours:
        n = len(contour)
        for i in range(n - 1):
            x1, y1 = contour[i]
            x2, y2 = contour[i + 1]

            # Skip horizontal edges
            if y1 == y2:
                continue

            # Check if scan line crosses this edge
            if (y1 <= y < y2) or (y2 <= y < y1):
                # Linear interpolation to find X at intersection
                t = (y - y1) / (y2 - y1)
                x = x1 + t * (x2 - x1)
                intersections.append(x)

    intersections.sort()
    return intersections


def get_filled_text_strokes(text, font_size_mm, center_x, center_y, line_spacing_mm):
    """
    Convert text to filled (raster) strokes for G-code using scan-line fill.

    Args:
        text: String to render (numeric like "42" or "18.5")
        font_size_mm: Height of characters in mm
        center_x, center_y: Center position for the text in mm
        line_spacing_mm: Distance between scan lines in mm

    Returns:
        List of strokes, where each stroke is a list of (x, y) points in mm.
        Compatible with generate_gcode_layer().
    """
    if line_spacing_mm <= 0:
        line_spacing_mm = 0.15

    strokes = []

    # Calculate total width of text using FILLED_CHAR_WIDTHS
    total_width = 0
    for char in text:
        total_width += FILLED_CHAR_WIDTHS.get(char, DEFAULT_CHAR_WIDTH)
    total_width += CHAR_SPACING * (len(text) - 1) if len(text) > 1 else 0
    total_width *= font_size_mm

    # Starting X position (left edge of first character)
    start_x = center_x - total_width / 2
    current_x = start_x

    # Y offset to center vertically
    y_offset = center_y - (font_size_mm * CHAR_HEIGHT) / 2

    # Collect all transformed contours for all characters
    all_contours = []
    for char in text:
        if char in FILLED_FONT:
            char_contours = FILLED_FONT[char]
            char_width = FILLED_CHAR_WIDTHS.get(char, DEFAULT_CHAR_WIDTH) * font_size_mm

            for contour in char_contours:
                transformed = []
                for px, py in contour:
                    x = current_x + px * font_size_mm
                    y = y_offset + py * font_size_mm
                    transformed.append((x, y))
                all_contours.append(transformed)

            current_x += char_width + CHAR_SPACING * font_size_mm
        else:
            current_x += DEFAULT_CHAR_WIDTH * font_size_mm + CHAR_SPACING * font_size_mm

    if not all_contours:
        return strokes

    # Find bounding box of all contours
    all_points = [p for c in all_contours for p in c]
    min_y = min(p[1] for p in all_points)
    max_y = max(p[1] for p in all_points)

    # Generate scan lines
    scan_y = min_y + line_spacing_mm / 2
    line_index = 0

    while scan_y < max_y:
        intersections = _scanline_intersections(all_contours, scan_y)

        # Pair up intersections using even-odd rule
        for i in range(0, len(intersections) - 1, 2):
            x_start = intersections[i]
            x_end = intersections[i + 1]
            if x_end - x_start > 0.01:  # Skip degenerate segments
                # Alternate direction for efficiency (reduces rapid moves)
                if line_index % 2 == 0:
                    strokes.append([(x_start, scan_y), (x_end, scan_y)])
                else:
                    strokes.append([(x_end, scan_y), (x_start, scan_y)])

        line_index += 1
        scan_y += line_spacing_mm

    return strokes


def get_filled_text_strokes_arc(text, font_size_mm, cx, cy, radius,
                                 center_angle_rad, line_spacing_mm,
                                 side='top'):
    """
    Lay out text along an arc using FILLED_FONT scan-line raster fill.

    Each character is filled with horizontal scan lines IN ITS OWN LOCAL
    FRAME (so the fill is always perpendicular to the character's baseline,
    regardless of where it sits on the arc), then each scan segment is
    rotated and translated into world coordinates so the character lies
    tangent to the arc.

    Use this when engraving_mode == "filled" so the credit text matches
    the visual style of the size labels.

    Args:
        text: String to render (must use FILLED_FONT chars)
        font_size_mm: Character height in mm
        cx, cy: Center of the arc circle in G-code coords (Y-up)
        radius: Radius of the text vertical center (mm)
        center_angle_rad: Angle (radians, math convention, Y-up) for the
                          centerline of the text. pi/2 = top, -pi/2 = bottom.
        line_spacing_mm: Spacing between scan lines in mm (same as flat
                         filled text)
        side: 'top' (sweep CW, char tops radially outward) or
              'bottom' (sweep CCW, char tops radially inward, so the text
              still reads upright when viewed from outside the circle)

    Returns:
        List of strokes, where each stroke is a list of (x, y) points in mm.
        Compatible with generate_gcode_layer().
    """
    strokes = []

    if radius <= 0 or font_size_mm <= 0 or not text:
        return strokes
    if line_spacing_mm <= 0:
        line_spacing_mm = 0.15

    # Total flat width (uses FILLED widths to match the flat filled renderer)
    total_width = 0.0
    for ch in text:
        total_width += FILLED_CHAR_WIDTHS.get(ch, DEFAULT_CHAR_WIDTH)
    if len(text) > 1:
        total_width += CHAR_SPACING * (len(text) - 1)
    total_width *= font_size_mm

    total_angular = total_width / radius

    if side == 'top':
        current_angle = center_angle_rad + total_angular / 2.0
        sweep_sign = -1.0

        def basis(theta):
            return (math.sin(theta), -math.cos(theta),
                    math.cos(theta), math.sin(theta))
    else:
        current_angle = center_angle_rad - total_angular / 2.0
        sweep_sign = 1.0

        def basis(theta):
            return (-math.sin(theta), math.cos(theta),
                    -math.cos(theta), -math.sin(theta))

    for char in text:
        char_w_glyph = FILLED_CHAR_WIDTHS.get(char, DEFAULT_CHAR_WIDTH)
        char_w_mm = char_w_glyph * font_size_mm
        char_angular_w = char_w_mm / radius

        char_center_angle = current_angle + sweep_sign * (char_angular_w / 2.0)

        ccx = cx + radius * math.cos(char_center_angle)
        ccy = cy + radius * math.sin(char_center_angle)
        tx, ty, rx, ry = basis(char_center_angle)

        if char in FILLED_FONT and FILLED_FONT[char]:
            # Build local-frame contours: glyph (px, py) -> centered mm.
            # px=0 is char left edge, px=char_w is char right edge,
            # py=0 is baseline, py=1 is top of cap.
            # Center: (char_w_glyph/2, 0.5) maps to local origin.
            local_contours = []
            for contour in FILLED_FONT[char]:
                local = []
                for px, py in contour:
                    lx = (px - char_w_glyph / 2.0) * font_size_mm
                    ly = (py - 0.5) * font_size_mm
                    local.append((lx, ly))
                local_contours.append(local)

            all_pts = [p for c in local_contours for p in c]
            if not all_pts:
                # advance and continue
                advance_mm = char_w_mm + CHAR_SPACING * font_size_mm
                current_angle += sweep_sign * (advance_mm / radius)
                continue

            min_y = min(p[1] for p in all_pts)
            max_y = max(p[1] for p in all_pts)

            scan_y = min_y + line_spacing_mm / 2.0
            line_index = 0
            while scan_y < max_y:
                intersections = _scanline_intersections(local_contours, scan_y)
                # Pair using even-odd fill rule
                for i in range(0, len(intersections) - 1, 2):
                    x_start = intersections[i]
                    x_end = intersections[i + 1]
                    if x_end - x_start > 0.01:
                        # Local (lx, ly) -> world via the basis
                        wx1 = ccx + x_start * tx + scan_y * rx
                        wy1 = ccy + x_start * ty + scan_y * ry
                        wx2 = ccx + x_end * tx + scan_y * rx
                        wy2 = ccy + x_end * ty + scan_y * ry
                        # Alternate scan direction (laser efficiency)
                        if line_index % 2 == 0:
                            strokes.append([(wx1, wy1), (wx2, wy2)])
                        else:
                            strokes.append([(wx2, wy2), (wx1, wy1)])
                line_index += 1
                scan_y += line_spacing_mm

        # Advance to next character
        advance_mm = char_w_mm + CHAR_SPACING * font_size_mm
        current_angle += sweep_sign * (advance_mm / radius)

    return strokes


def get_text_strokes_arc(text, font_size_mm, cx, cy, radius,
                         center_angle_rad, side='top'):
    """
    Lay out text along an arc using STROKE_FONT, producing rigid characters
    rotated to follow the curve.

    Each character is placed as a rigid rotated unit (not warped). Use this
    for the Phil Noy credit engraving on the die holder ring (top of circle)
    and the die insert ring (bottom of circle, opposite the size number).

    Args:
        text: String to render (must use STROKE_FONT chars)
        font_size_mm: Character height in mm
        cx, cy: Center of the arc circle in G-code coords (Y-up)
        radius: Radius of the text baseline (mm) — character verticals are
                centered on this radius, extending +/- font_size_mm/2 in the
                radial direction
        center_angle_rad: Angle (radians, math convention, Y-up) of the
                          centerline of the text. pi/2 = top of circle,
                          -pi/2 = bottom.
        side: 'top' — text upright above the radius, sweep CW
              'bottom' — text upright below the radius, sweep CCW

    Returns:
        List of strokes, where each stroke is a list of (x, y) points in mm.
    """
    strokes = []

    if radius <= 0 or font_size_mm <= 0 or not text:
        return strokes

    # Total flat width of the text (mm)
    total_width = 0.0
    for char in text:
        total_width += CHAR_WIDTHS.get(char, DEFAULT_CHAR_WIDTH)
    if len(text) > 1:
        total_width += CHAR_SPACING * (len(text) - 1)
    total_width *= font_size_mm

    total_angular = total_width / radius  # radians

    if side == 'top':
        # Sweep CW (decreasing angle). At the top, the local X axis (along
        # baseline, char-left to char-right) is the CW tangent direction;
        # the local Y axis (baseline to char-top) is radially outward.
        current_angle = center_angle_rad + total_angular / 2.0
        sweep_sign = -1.0

        def basis(theta):
            return (math.sin(theta), -math.cos(theta),
                    math.cos(theta), math.sin(theta))
    else:
        # 'bottom' — sweep CCW (increasing angle). Local X is CCW tangent;
        # local Y is radially INWARD (so the character reads upright to the
        # viewer when the circle is in normal orientation).
        current_angle = center_angle_rad - total_angular / 2.0
        sweep_sign = 1.0

        def basis(theta):
            return (-math.sin(theta), math.cos(theta),
                    -math.cos(theta), -math.sin(theta))

    for char in text:
        char_w_glyph = CHAR_WIDTHS.get(char, DEFAULT_CHAR_WIDTH)
        char_w_mm = char_w_glyph * font_size_mm
        char_angular_w = char_w_mm / radius

        # Center angle of this character
        char_center_angle = current_angle + sweep_sign * (char_angular_w / 2.0)

        # Char center point on the arc circle
        ccx = cx + radius * math.cos(char_center_angle)
        ccy = cy + radius * math.sin(char_center_angle)

        # Local basis at this angle
        tx, ty, rx, ry = basis(char_center_angle)

        if char in STROKE_FONT:
            for stroke in STROKE_FONT[char]:
                transformed = []
                for px, py in stroke:
                    # Glyph-local coords centered on (char_w/2, 0.5)
                    lx = (px - char_w_glyph / 2.0) * font_size_mm
                    ly = (py - 0.5) * font_size_mm
                    wx = ccx + lx * tx + ly * rx
                    wy = ccy + lx * ty + ly * ry
                    transformed.append((wx, wy))
                strokes.append(transformed)

        # Advance angle (include inter-char spacing)
        advance_mm = char_w_mm + CHAR_SPACING * font_size_mm
        current_angle += sweep_sign * (advance_mm / radius)

    return strokes


def get_text_strokes(text, font_size_mm, center_x, center_y):
    """
    Convert text (numbers) to stroke paths for G-code.

    Args:
        text: String to render (should be numeric like "42" or "18.5")
        font_size_mm: Height of characters in mm
        center_x, center_y: Center position for the text in mm

    Returns:
        List of strokes, where each stroke is a list of (x, y) points in mm
    """
    strokes = []

    # Calculate total width of text
    total_width = 0
    for char in text:
        total_width += CHAR_WIDTHS.get(char, DEFAULT_CHAR_WIDTH)
    total_width += CHAR_SPACING * (len(text) - 1) if len(text) > 1 else 0
    total_width *= font_size_mm

    # Starting X position (left edge of first character)
    start_x = center_x - total_width / 2
    current_x = start_x

    # Y offset to center vertically
    y_offset = center_y - (font_size_mm * CHAR_HEIGHT) / 2

    for char in text:
        if char in STROKE_FONT:
            char_strokes = STROKE_FONT[char]
            char_width = CHAR_WIDTHS.get(char, DEFAULT_CHAR_WIDTH) * font_size_mm

            for stroke in char_strokes:
                transformed_stroke = []
                for px, py in stroke:
                    # Scale and translate
                    x = current_x + px * font_size_mm
                    y = y_offset + py * font_size_mm
                    transformed_stroke.append((x, y))
                strokes.append(transformed_stroke)

            current_x += char_width + CHAR_SPACING * font_size_mm
        else:
            # Skip unknown characters, but advance position
            current_x += DEFAULT_CHAR_WIDTH * font_size_mm + CHAR_SPACING * font_size_mm

    return strokes


# =============================================================================
# CIRCLE LINEARIZATION
# =============================================================================

def linearize_circle(cx, cy, radius, segments=72):
    """
    Convert a circle to a list of line segment points.

    Args:
        cx, cy: Center coordinates in mm
        radius: Radius in mm
        segments: Number of line segments (default 72 = 5-degree steps)

    Returns:
        List of (x, y) points forming a closed polygon
    """
    points = []
    for i in range(segments + 1):
        angle = 2 * math.pi * i / segments
        x = cx + radius * math.cos(angle)
        y = cy + radius * math.sin(angle)
        points.append((x, y))
    return points


# =============================================================================
# STAR PATH CONVERSION
# =============================================================================

def parse_svg_path_to_points(path_d):
    """
    Parse an SVG path 'd' attribute to extract points.
    Handles M (move), L (line), and Z (close) commands.

    This is a simplified parser for the star paths generated by svg_engine.

    Args:
        path_d: SVG path 'd' attribute string

    Returns:
        List of (x, y) points
    """
    points = []
    # Remove commas and split by spaces
    path_d = path_d.replace(',', ' ')
    tokens = path_d.split()

    i = 0
    current_x, current_y = 0, 0
    start_x, start_y = 0, 0

    while i < len(tokens):
        token = tokens[i]

        if token == 'M':
            # Move to absolute
            current_x = float(tokens[i + 1])
            current_y = float(tokens[i + 2])
            start_x, start_y = current_x, current_y
            points.append((current_x, current_y))
            i += 3
        elif token == 'm':
            # Move to relative
            current_x += float(tokens[i + 1])
            current_y += float(tokens[i + 2])
            start_x, start_y = current_x, current_y
            points.append((current_x, current_y))
            i += 3
        elif token == 'L':
            # Line to absolute
            current_x = float(tokens[i + 1])
            current_y = float(tokens[i + 2])
            points.append((current_x, current_y))
            i += 3
        elif token == 'l':
            # Line to relative
            current_x += float(tokens[i + 1])
            current_y += float(tokens[i + 2])
            points.append((current_x, current_y))
            i += 3
        elif token == 'Z' or token == 'z':
            # Close path - return to start
            if points and (current_x != start_x or current_y != start_y):
                points.append((start_x, start_y))
            i += 1
        elif token == 'H':
            # Horizontal line absolute
            current_x = float(tokens[i + 1])
            points.append((current_x, current_y))
            i += 2
        elif token == 'h':
            # Horizontal line relative
            current_x += float(tokens[i + 1])
            points.append((current_x, current_y))
            i += 2
        elif token == 'V':
            # Vertical line absolute
            current_y = float(tokens[i + 1])
            points.append((current_x, current_y))
            i += 2
        elif token == 'v':
            # Vertical line relative
            current_y += float(tokens[i + 1])
            points.append((current_x, current_y))
            i += 2
        else:
            # Try to parse as coordinate pair (implicit L command)
            try:
                x = float(token)
                y = float(tokens[i + 1])
                current_x, current_y = x, y
                points.append((current_x, current_y))
                i += 2
            except (ValueError, IndexError):
                i += 1

    return points


# =============================================================================
# G-CODE GENERATION
# =============================================================================

def _generate_star_points(cx, cy, outer_r, inner_r, num_points, shape_factor=0.0):
    """
    Generate star/dart pattern points for G-code.

    Uses the same math as calculate_star_path() in svg_engine.py but returns
    a list of (x, y) points instead of an SVG path string.

    Args:
        cx, cy: Center coordinates
        outer_r: Outer (tip) radius
        inner_r: Inner (valley) radius
        num_points: Number of points (tips) on the star
        shape_factor: 0.0 = sine wave, 1.0 = flattened (square-ish)

    Returns:
        List of (x, y) points forming a closed star shape
    """
    points = []

    avg_r = (outer_r + inner_r) / 2.0
    amplitude = (outer_r - inner_r) / 2.0

    steps = int(num_points * 8)
    if steps < 64:
        steps = 64

    angle_step = (2 * math.pi) / steps
    power = 1.0 - (0.9 * shape_factor)

    for i in range(steps + 1):
        theta = i * angle_step

        raw_wave = math.cos(num_points * theta)
        shaped_wave = (1 if raw_wave >= 0 else -1) * (abs(raw_wave) ** power)

        r = avg_r + amplitude * shaped_wave

        x = cx + r * math.cos(theta)
        y = cy + r * math.sin(theta)
        points.append((x, y))

    return points


def generate_gcode_header(bounds_min_x, bounds_min_y, bounds_max_x, bounds_max_y):
    """Generate G-code file header."""
    lines = [
        "; Generated by Stohrer Sax Shop Companion",
        "; GRBL device profile, absolute coords",
        f"; Bounds: X{bounds_min_x:.2f} Y{bounds_min_y:.2f} to X{bounds_max_x:.2f} Y{bounds_max_y:.2f}",
        "G00 G17 G40 G21 G54",
        "G90",
        "M4",
    ]
    return lines


def generate_gcode_footer(return_speed=1000):
    """Generate G-code file footer.

    Args:
        return_speed: Feed rate in mm/min for the return-to-home move.
    """
    lines = [
        "M9",
        "G1 S0",
        "G90",
        "; return to origin",
        f"G1 X0Y0 F{return_speed}",
        "M5",
        "M2",
    ]
    return lines


def generate_gcode_layer(strokes, speed_mm_min, power_percent, layer_name, overscan_mm=0, air_assist=True, passes=1):
    """
    Generate G-code for a layer (set of strokes).

    Args:
        strokes: List of strokes, where each stroke is a list of (x, y) points
        speed_mm_min: Feed rate in mm/min
        power_percent: Laser power as percentage (0-100)
        layer_name: Layer name for comment
        overscan_mm: If > 0, extend horizontal 2-point scan lines by this amount
                     on each side with laser off, so the head is at full speed
                     when it reaches the actual fill area.
        air_assist: If True, emit M8 (air on); if False, emit M9 (air off).
        passes: Number of times to run the strokes (>=1). Useful for thicker
                materials where multiple lower-power passes cut cleaner than
                one high-power pass.

    Returns:
        List of G-code lines
    """
    if not strokes:
        return []

    try:
        passes = int(passes)
    except (TypeError, ValueError):
        passes = 1
    if passes < 1:
        passes = 1

    lines = []

    # Layer header
    pass_note = f", x{passes} passes" if passes > 1 else ""
    lines.append(f"; Cut @ {speed_mm_min} mm/min, {power_percent}% power{pass_note}")
    lines.append("M8" if air_assist else "M9")

    # Power value for S parameter (percentage * 10 for 0-1000 scale)
    s_value = int(power_percent * 10)

    for pass_idx in range(passes):
        if passes > 1:
            lines.append(f"; Pass {pass_idx + 1} of {passes}")
        first_move = True

        for stroke in strokes:
            if len(stroke) < 2:
                continue

            # Check if this is a horizontal scan line eligible for overscan
            is_scanline = (overscan_mm > 0 and len(stroke) == 2
                           and abs(stroke[0][1] - stroke[1][1]) < 0.001)

            if is_scanline:
                x0, y0 = stroke[0]
                x1, y1 = stroke[1]
                # Determine scan direction and extend
                if x1 > x0:
                    approach_x = x0 - overscan_mm
                    exit_x = x1 + overscan_mm
                else:
                    approach_x = x0 + overscan_mm
                    exit_x = x1 - overscan_mm

                # Rapid to overscan start
                lines.append(f"G0 X{approach_x:.3f}Y{y0:.3f}")
                if first_move:
                    lines.append(f"; Layer {layer_name}")
                    first_move = False
                # Approach at engrave speed, laser off
                lines.append(f"G1 X{x0:.3f}Y{y0:.3f}S0F{speed_mm_min}")
                # Engrave through fill area, laser on
                lines.append(f"G1 X{x1:.3f}S{s_value}")
                # Exit overscan, laser off
                lines.append(f"G1 X{exit_x:.3f}S0")
            else:
                # Standard stroke: rapid to start, then cut
                x0, y0 = stroke[0]
                lines.append(f"G0 X{x0:.3f}Y{y0:.3f}")

                if first_move:
                    lines.append(f"; Layer {layer_name}")
                    first_move = False

                # Cut moves
                for i, (x, y) in enumerate(stroke[1:], 1):
                    if i == 1:
                        lines.append(f"G1 X{x:.3f}Y{y:.3f}S{s_value}F{speed_mm_min}")
                    else:
                        lines.append(f"G1 X{x:.3f}Y{y:.3f}")

    return lines


def generate_gcode(pads, material, sheet_width_mm, sheet_height_mm, filename,
                   hole_dia, settings, polygon=None):
    """
    Generate G-code file for laser cutting pads.

    This mirrors the generate_svg function but outputs G-code instead.

    Args:
        pads: List of pad dictionaries with 'size' and 'qty' keys
        material: Material type ('felt', 'card', 'leather')
        sheet_width_mm, sheet_height_mm: Sheet dimensions in mm
        filename: Output filename
        hole_dia: Center hole diameter in mm (0 for no hole)
        settings: App settings dictionary
        polygon: Optional custom polygon shape
    """
    from svg_engine import _nest_discs

    # Use the same nesting as SVG generation
    placed, _, _ = _nest_discs(pads, material, sheet_width_mm, sheet_height_mm, settings, polygon=polygon)

    if not placed:
        return

    generate_gcode_from_placed(placed, material, sheet_width_mm, sheet_height_mm, filename,
                                hole_dia, settings, polygon=polygon)


def can_generate_gcode(material):
    """Check if G-code generation is supported for a material."""
    return material in ('felt', 'card', 'leather', 'die_ring', 'acrylic')


def generate_gcode_from_placed(placed, material, sheet_width_mm, sheet_height_mm, filename,
                                hole_dia, settings, polygon=None):
    """
    Generate G-code file from pre-computed placed discs.

    This is used by scrap mode where nesting is done separately via try_nest_partial().
    The function generates G-code for the placed discs without re-running nesting.

    Args:
        placed: List of (pad_size, cx, cy, radius) tuples from nesting
        material: Material type ('felt', 'card', 'leather')
        sheet_width_mm, sheet_height_mm: Sheet dimensions in mm
        filename: Output filename
        hole_dia: Center hole diameter in mm (0 for no hole)
        settings: App settings dictionary
        polygon: Optional polygon shape; when provided, its bounding box height
                 is used for Y-flip instead of sheet_height_mm
    """
    from svg_engine import get_felt_thickness_mm
    from config import (get_dart_settings_for_size, get_sizing_for_size,
                        get_engraving_settings_for_size, get_engraving_placement_for_size)

    if not placed:
        return

    # Flip Y coordinates for G-code: SVG uses Y=0 at top, G-code uses Y=0 at bottom
    # When a polygon is used, its bounding box defines the coordinate space
    if polygon:
        flip_height = max(p[1] for p in polygon)
    else:
        flip_height = sheet_height_mm
    placed = [(pad_size, cx, flip_height - cy, radius) for (pad_size, cx, cy, radius) in placed]

    # Get G-code settings for this material
    gcode_settings = settings.get("gcode_settings", {})
    mat_settings = gcode_settings.get(material, gcode_settings.get("felt", {}))

    engraving_mode = mat_settings.get("engraving_mode", "line")
    if engraving_mode == "filled":
        engraving_speed = mat_settings.get("filled_engraving_speed", 1000)
        engraving_power = mat_settings.get("filled_engraving_power", 12)
        engraving_passes = mat_settings.get("filled_engraving_passes", 1)
        filled_line_spacing = mat_settings.get("filled_line_spacing", 0.15)
    else:
        engraving_speed = mat_settings.get("engraving_speed", 1500)
        engraving_power = mat_settings.get("engraving_power", 10)
        engraving_passes = mat_settings.get("engraving_passes", 1)

    # Overscan: extend filled scan lines so the head is at speed at the character edge
    overscan_mm = 0
    if engraving_mode == "filled" and settings.get("filled_overscan_enabled", False):
        overscan_mm = settings.get("filled_overscan_mm", 1.5)
    hole_speed = mat_settings.get("hole_speed", 400)
    hole_power = mat_settings.get("hole_power", 25)
    hole_passes = mat_settings.get("hole_passes", 1)
    cut_speed = mat_settings.get("cut_speed", 900)
    cut_power = mat_settings.get("cut_power", 35)
    cut_passes = mat_settings.get("cut_passes", 1)

    # Global G-code options
    return_speed = settings.get("gcode_return_speed", 1000)
    cut_grouping = settings.get("gcode_cut_grouping", "layer")

    # Air assist per layer type
    if engraving_mode == "filled":
        air_assist_engraving = mat_settings.get("air_assist_filled_engraving", True)
    else:
        air_assist_engraving = mat_settings.get("air_assist_engraving", True)
    air_assist_hole = mat_settings.get("air_assist_hole", True)
    air_assist_cut = mat_settings.get("air_assist_cut", True)

    # Kerf compensation (applied to cuts, not engraving) - per material
    kerf_width = mat_settings.get("kerf_width", 0.0)
    kerf_offset = kerf_width / 2

    # Track bounds
    all_x = []
    all_y = []

    def _collect_disc_strokes(pad_size, cx, cy, radius):
        """Collect engraving, hole, and cut strokes for a single disc."""
        disc_eng = []
        disc_hole = []
        disc_cut = []

        sizing = get_sizing_for_size(pad_size, settings)
        eng_cfg = get_engraving_settings_for_size(pad_size, settings)
        plc_cfg = get_engraving_placement_for_size(pad_size, settings)
        font_size = eng_cfg.get("engraving_font_size", {}).get(material, 3.0)

        dart_cfg = get_dart_settings_for_size(pad_size, settings) if material == 'leather' else None
        is_dart_pad = dart_cfg is not None

        # Engraving
        should_engrave = False
        eng_settings = None

        if is_dart_pad:
            if dart_cfg.get("engraving_on", True):
                eng_settings = plc_cfg.get("engraving_location", {}).get("darted_leather", {"mode": "from_outside", "value": 2.5})
                should_engrave = True
        else:
            if eng_cfg.get("engraving_on", True):
                eng_settings = plc_cfg.get("engraving_location", {}).get(material, {"mode": "centered", "value": 0})
                should_engrave = True

        if should_engrave and font_size >= radius * 0.8:
            should_engrave = False

        if should_engrave:
            mode = eng_settings.get('mode', 'centered')
            value = eng_settings.get('value', 0)

            if mode == 'from_outside':
                engraving_y = cy - (radius - value)
            elif mode == 'from_inside':
                hole_r = hole_dia / 2 if hole_dia > 0 else 0
                engraving_y = cy - (hole_r + value)
            else:  # centered
                hole_r = hole_dia / 2 if hole_dia > 0 else 1.75
                offset_from_center = (radius + hole_r) / 2
                engraving_y = cy - offset_from_center

            vertical_adjust = font_size * 0.35
            label_y = engraving_y + vertical_adjust

            text = f"{pad_size:.1f}".rstrip('0').rstrip('.')

            # Auto-fit: shift text toward center if it impinges on disc edge
            min_clearance = 0.5  # mm from any stroke point to cut line
            disc_font_size = font_size
            if engraving_mode == "filled":
                text_strokes = get_filled_text_strokes(text, disc_font_size, cx, label_y, filled_line_spacing)
            else:
                text_strokes = get_text_strokes(text, disc_font_size, cx, label_y)

            # Find farthest stroke point from disc center
            max_dist = 0
            for stroke in text_strokes:
                for px, py in stroke:
                    dist = math.sqrt((px - cx)**2 + (py - cy)**2)
                    if dist > max_dist:
                        max_dist = dist

            # Prefer shifting toward center over shrinking for readability
            safe_radius = radius - min_clearance
            if max_dist > safe_radius > 0:
                # Compute stroke extents for shift-vs-scale decision
                max_horiz = max((abs(px - cx) for stroke in text_strokes for px, py in stroke), default=0)
                max_vert = max((abs(py - label_y) for stroke in text_strokes for px, py in stroke), default=0)
                centered_max_dist = math.sqrt(max_horiz**2 + max_vert**2)

                if centered_max_dist <= safe_radius:
                    # Fits at full size — shift toward center just enough
                    max_offset = math.sqrt(safe_radius**2 - max_horiz**2) - max_vert
                    dy = label_y - cy
                    new_label_y = label_y
                    if abs(dy) > max_offset:
                        new_label_y = cy + math.copysign(max_offset, dy)
                    if new_label_y != label_y:
                        if engraving_mode == "filled":
                            text_strokes = get_filled_text_strokes(text, disc_font_size, cx, new_label_y, filled_line_spacing)
                        else:
                            text_strokes = get_text_strokes(text, disc_font_size, cx, new_label_y)
                else:
                    # Too large even centered — center and scale as last resort
                    scale = safe_radius / centered_max_dist
                    disc_font_size *= scale
                    if engraving_mode == "filled":
                        text_strokes = get_filled_text_strokes(text, disc_font_size, cx, cy, filled_line_spacing)
                    else:
                        text_strokes = get_text_strokes(text, disc_font_size, cx, cy)
            disc_eng.extend(text_strokes)

        # Center hole
        if hole_dia > 0 and pad_size >= sizing.get("min_hole_size", 16.5):
            hole_radius = (hole_dia / 2) - kerf_offset
            if hole_radius > 0:
                hole_points = linearize_circle(cx, cy, hole_radius, segments=36)
                disc_hole.append(hole_points)

        # Outer cut - circle or star pattern
        if is_dart_pad:
            felt_thick = get_felt_thickness_mm(settings, sizing)
            overwrap = dart_cfg.get("overwrap", 0.5)

            felt_r = (pad_size - sizing.get("felt_offset", 0.75)) / 2
            inner_r = felt_r + felt_thick + overwrap
            outer_r = radius

            if inner_r >= outer_r:
                inner_r = outer_r - 0.2

            outer_r += kerf_offset
            inner_r += kerf_offset

            circumference = 2 * math.pi * inner_r
            freq_mult = dart_cfg.get("frequency_multiplier", 1.0)
            num_points = int((circumference / 3.5) * freq_mult)
            if num_points < 12:
                num_points = 12
            if num_points % 2 != 0:
                num_points += 1

            shape_factor = dart_cfg.get("shape_factor", 0.0)
            star_points = _generate_star_points(cx, cy, outer_r, inner_r, num_points, shape_factor)
            disc_cut.append(star_points)
        else:
            cut_radius = radius + kerf_offset
            cut_points = linearize_circle(cx, cy, cut_radius, segments=72)
            disc_cut.append(cut_points)

        return disc_eng, disc_hole, disc_cut

    # Compute bounds
    for pad_size, cx, cy, radius in placed:
        all_x.extend([cx - radius, cx + radius])
        all_y.extend([cy - radius, cy + radius])

    # Generate G-code
    gcode_lines = []

    bounds_min_x = min(all_x) if all_x else 0
    bounds_min_y = min(all_y) if all_y else 0
    bounds_max_x = max(all_x) if all_x else sheet_width_mm
    bounds_max_y = max(all_y) if all_y else sheet_height_mm
    gcode_lines.extend(generate_gcode_header(bounds_min_x, bounds_min_y, bounds_max_x, bounds_max_y))

    layer_names = {
        'felt': ('C10', 'C09', 'C00'),
        'card': ('C15', 'C14', 'C01'),
        'leather': ('C05', 'C03', 'C02'),
    }
    eng_layer, hole_layer, cut_layer = layer_names.get(material, ('C00', 'C01', 'C02'))

    if cut_grouping == "pad":
        # Per-pad grouping: engrave + hole + cut for each disc
        for pad_size, cx, cy, radius in placed:
            disc_eng, disc_hole, disc_cut = _collect_disc_strokes(pad_size, cx, cy, radius)

            if disc_eng:
                gcode_lines.extend(generate_gcode_layer(disc_eng, engraving_speed, engraving_power, eng_layer,
                                                         overscan_mm=overscan_mm, air_assist=air_assist_engraving,
                                                         passes=engraving_passes))
            if disc_hole:
                gcode_lines.extend(generate_gcode_layer(disc_hole, hole_speed, hole_power, hole_layer,
                                                         air_assist=air_assist_hole, passes=hole_passes))
            if disc_cut:
                gcode_lines.extend(generate_gcode_layer(disc_cut, cut_speed, cut_power, cut_layer,
                                                         air_assist=air_assist_cut, passes=cut_passes))
    else:
        # Layer grouping (default): all engravings, then all holes, then all cuts
        engraving_strokes = []
        hole_strokes = []
        cut_strokes = []

        for pad_size, cx, cy, radius in placed:
            disc_eng, disc_hole, disc_cut = _collect_disc_strokes(pad_size, cx, cy, radius)
            engraving_strokes.extend(disc_eng)
            hole_strokes.extend(disc_hole)
            cut_strokes.extend(disc_cut)

        if engraving_strokes:
            gcode_lines.extend(generate_gcode_layer(engraving_strokes, engraving_speed, engraving_power, eng_layer,
                                                     overscan_mm=overscan_mm, air_assist=air_assist_engraving,
                                                     passes=engraving_passes))

        if hole_strokes:
            gcode_lines.extend(generate_gcode_layer(hole_strokes, hole_speed, hole_power, hole_layer,
                                                     air_assist=air_assist_hole, passes=hole_passes))

        if cut_strokes:
            gcode_lines.extend(generate_gcode_layer(cut_strokes, cut_speed, cut_power, cut_layer,
                                                     air_assist=air_assist_cut, passes=cut_passes))

    gcode_lines.extend(generate_gcode_footer(return_speed=return_speed))

    with open(filename, 'w') as f:
        f.write('\n'.join(gcode_lines))


# ==========================================
# DIE INSERT G-CODE GENERATION
# ==========================================

def generate_die_gcode_from_placed(placed, sheet_width_mm, sheet_height_mm, filename, settings):
    """
    Generate G-code for die insert rings from pre-computed placements.

    Each die ring has: optional ring engraving, optional cutout engraving,
    inner cut (pad-sized hole), outer cut (die boundary).
    Cut order: engravings → inner cuts → outer cuts (so ring stays in place).
    """
    if not placed:
        return

    # Flip Y coordinates for G-code
    flip_height = sheet_height_mm
    placed = [(pad_size, cx, flip_height - cy, radius) for (pad_size, cx, cy, radius) in placed]

    # Get acrylic G-code settings
    gcode_settings = settings.get("gcode_settings", {})
    mat_settings = gcode_settings.get("acrylic", {})
    tooling = settings.get("tooling_settings", {})

    engraving_mode = mat_settings.get("engraving_mode", "filled")
    if engraving_mode == "filled":
        engraving_speed = mat_settings.get("filled_engraving_speed", 800)
        engraving_power = mat_settings.get("filled_engraving_power", 15)
        engraving_passes = mat_settings.get("filled_engraving_passes", 1)
        filled_line_spacing = mat_settings.get("filled_line_spacing", 0.15)
    else:
        engraving_speed = mat_settings.get("engraving_speed", 800)
        engraving_power = mat_settings.get("engraving_power", 15)
        engraving_passes = mat_settings.get("engraving_passes", 1)

    overscan_mm = 0
    if engraving_mode == "filled" and settings.get("filled_overscan_enabled", False):
        overscan_mm = settings.get("filled_overscan_mm", 1.5)

    cut_speed = mat_settings.get("cut_speed", 150)
    cut_power = mat_settings.get("cut_power", 100)
    cut_passes = mat_settings.get("cut_passes", 1)

    kerf_width = mat_settings.get("kerf_width", 0.15)
    kerf_offset = kerf_width / 2

    return_speed = settings.get("gcode_return_speed", 1000)

    engrave_ring = tooling.get("engrave_ring", True)
    engrave_cutout = tooling.get("engrave_cutout", True)
    ring_font_size = tooling.get("ring_font_size", 3.5)
    cutout_font_size = tooling.get("cutout_font_size", 3.5)
    ring_location = tooling.get("ring_engraving_location", "centered")
    ring_offset = tooling.get("ring_engraving_offset", 0.0)

    if engraving_mode == "filled":
        air_assist_engraving = mat_settings.get("air_assist_filled_engraving", True)
    else:
        air_assist_engraving = mat_settings.get("air_assist_engraving", True)
    air_assist_cut = mat_settings.get("air_assist_cut", True)

    # Collect strokes
    engraving_strokes = []
    inner_cut_strokes = []
    outer_cut_strokes = []

    for pad_size, cx, cy, radius in placed:
        inner_r = pad_size / 2

        # Ring engraving (pad size on ring annulus)
        if engrave_ring:
            text_content = f"{pad_size:.1f}".rstrip('0').rstrip('.')
            ring_width = radius - inner_r
            font_size = ring_font_size
            if font_size > ring_width * 0.9:
                font_size = ring_width * 0.9
            if font_size < 1.0:
                font_size = 1.0

            # G-code Y is flipped vs SVG
            if ring_location == "from_outside":
                label_y = cy + (radius - ring_offset) - font_size * 0.35
            else:  # centered
                ring_center_r = (radius + inner_r) / 2
                label_y = cy + ring_center_r - font_size * 0.35

            if engraving_mode == "filled":
                strokes = get_filled_text_strokes(text_content, font_size, cx, label_y, filled_line_spacing)
            else:
                strokes = get_text_strokes(text_content, font_size, cx, label_y)
            engraving_strokes.extend(strokes)

            # "NOY" arced opposite the size number (Phil Noy credit on
            # each die insert). Same engraving mode as the size label so
            # the visual style is consistent.
            ring_center_r = (radius + inner_r) / 2
            # Y-up gcode: -pi/2 = bottom of circle
            if engraving_mode == "filled":
                noy_strokes = get_filled_text_strokes_arc(
                    "NOY", font_size,
                    cx, cy, ring_center_r, -math.pi / 2.0,
                    filled_line_spacing, side='bottom')
            else:
                noy_strokes = get_text_strokes_arc(
                    "NOY", font_size,
                    cx, cy, ring_center_r, -math.pi / 2.0, side='bottom')
            engraving_strokes.extend(noy_strokes)

        # Cutout engraving (actual size on inner disc)
        if engrave_cutout:
            actual_size = pad_size - kerf_width
            text_content = f"{actual_size:.2f}".rstrip('0').rstrip('.')
            font_size = cutout_font_size
            if inner_r > font_size:
                label_y = cy - font_size * 0.35  # Centered in inner disc

                if engraving_mode == "filled":
                    strokes = get_filled_text_strokes(text_content, font_size, cx, label_y, filled_line_spacing)
                else:
                    strokes = get_text_strokes(text_content, font_size, cx, label_y)
                engraving_strokes.extend(strokes)

        # Inner cut (pad hole) - shrink by kerf offset
        inner_cut_r = inner_r - kerf_offset
        if inner_cut_r > 0:
            inner_cut_strokes.append(linearize_circle(cx, cy, inner_cut_r, segments=72))

        # Outer cut (die boundary) - expand by kerf offset
        outer_cut_r = radius + kerf_offset
        outer_cut_strokes.append(linearize_circle(cx, cy, outer_cut_r, segments=72))

    # Build G-code: engravings → inner cuts → outer cuts
    all_x = []
    all_y = []
    for pad_size, cx, cy, radius in placed:
        all_x.extend([cx - radius, cx + radius])
        all_y.extend([cy - radius, cy + radius])

    gcode_lines = []
    bounds_min_x = min(all_x) if all_x else 0
    bounds_min_y = min(all_y) if all_y else 0
    bounds_max_x = max(all_x) if all_x else sheet_width_mm
    bounds_max_y = max(all_y) if all_y else sheet_height_mm
    gcode_lines.extend(generate_gcode_header(bounds_min_x, bounds_min_y, bounds_max_x, bounds_max_y))

    if engraving_strokes:
        gcode_lines.extend(generate_gcode_layer(engraving_strokes, engraving_speed, engraving_power, 'C03',
                                                 overscan_mm=overscan_mm, air_assist=air_assist_engraving,
                                                 passes=engraving_passes))
    if inner_cut_strokes:
        gcode_lines.extend(generate_gcode_layer(inner_cut_strokes, cut_speed, cut_power, 'C01',
                                                 air_assist=air_assist_cut, passes=cut_passes))
    if outer_cut_strokes:
        gcode_lines.extend(generate_gcode_layer(outer_cut_strokes, cut_speed, cut_power, 'C02',
                                                 air_assist=air_assist_cut, passes=cut_passes))

    gcode_lines.extend(generate_gcode_footer(return_speed=return_speed))

    with open(filename, 'w') as f:
        f.write('\n'.join(gcode_lines))


# ==========================================
# DIE HOLDER G-CODE GENERATION
# ==========================================

def generate_holder_gcode(variant, filename, settings, *,
                          layer_count=6,
                          sheet_width_mm=None, sheet_height_mm=None):
    """
    Generate G-code for die holder pieces.

    Args:
        variant: "large", "small", or "both" (both = two complete holders)
        filename: Output file path
        settings: App settings dict
        layer_count: 5 (2x pin) or 6 (3x pin). Default 6.
        sheet_width_mm, sheet_height_mm: User sheet size; raises ValueError
            if pieces don't fit. None = legacy auto-size.
    """
    from svg_engine import (HOLDER_OUTER_R, HOLDER_MAGNET_HOLE_R, HOLDER_PIN_HOLE_R,
                            _holder_pieces_for, _pack_holder_grid, _min_holder_sheet)

    gcode_settings = settings.get("gcode_settings", {})
    mat_settings = gcode_settings.get("acrylic", {})

    hole_speed = mat_settings.get("hole_speed", 200)
    hole_power = mat_settings.get("hole_power", 80)
    hole_passes = mat_settings.get("hole_passes", 1)
    cut_speed = mat_settings.get("cut_speed", 150)
    cut_power = mat_settings.get("cut_power", 100)
    cut_passes = mat_settings.get("cut_passes", 1)
    kerf_width = mat_settings.get("kerf_width", 0.15)
    kerf_offset = kerf_width / 2
    return_speed = settings.get("gcode_return_speed", 1000)
    air_assist_hole = mat_settings.get("air_assist_hole", True)
    air_assist_cut = mat_settings.get("air_assist_cut", True)

    spacing = 5.0
    outer_d = HOLDER_OUTER_R * 2

    pieces = _holder_pieces_for(variant, layer_count)
    num_pieces = len(pieces)

    if sheet_width_mm is not None and sheet_height_mm is not None:
        layout = _pack_holder_grid(num_pieces, sheet_width_mm, sheet_height_mm,
                                   outer_d, spacing)
        if layout is None:
            min_w, min_h = _min_holder_sheet(num_pieces, outer_d, spacing)
            raise ValueError(
                f"{num_pieces} holder pieces don't fit on a "
                f"{sheet_width_mm:.0f} × {sheet_height_mm:.0f} mm sheet. "
                f"Need at least {min_w:.0f} × {min_h:.0f} mm."
            )
        cols, rows = layout
        width_mm = sheet_width_mm
        height_mm = sheet_height_mm
    else:
        cols = max(1, math.ceil(math.sqrt(num_pieces)))
        rows = (num_pieces + cols - 1) // cols
        width_mm = cols * outer_d + (cols + 1) * spacing
        height_mm = rows * outer_d + (rows + 1) * spacing

    hole_strokes = []
    outer_cut_strokes = []
    inner_cut_strokes = []
    engraving_strokes = []
    engraving_mode = mat_settings.get("engraving_mode", "filled")
    eng_speed = mat_settings.get("engraving_speed", 800)
    eng_power = mat_settings.get("engraving_power", 15)
    eng_passes = mat_settings.get("engraving_passes", 1)

    for i, (piece_type, inner_r) in enumerate(pieces):
        col = i % cols
        row = i // cols
        cx = spacing + HOLDER_OUTER_R + col * (outer_d + spacing)
        # G-code Y flip: Y=0 at bottom
        svg_cy = spacing + HOLDER_OUTER_R + row * (outer_d + spacing)
        cy = height_mm - svg_cy

        # Outer circle (always present)
        outer_cut_strokes.append(linearize_circle(cx, cy, HOLDER_OUTER_R + kerf_offset, segments=72))

        if piece_type == 'magnet':
            # 6.5mm dia magnet hole
            hole_strokes.append(linearize_circle(cx, cy, HOLDER_MAGNET_HOLE_R - kerf_offset, segments=36))

        elif piece_type == 'pin':
            # 3.5mm dia alignment hole
            hole_strokes.append(linearize_circle(cx, cy, HOLDER_PIN_HOLE_R - kerf_offset, segments=36))

        elif piece_type == 'ring':
            inner_cut_strokes.append(linearize_circle(cx, cy, inner_r - kerf_offset, segments=72))

            # "DESIGNED BY PHIL NOY" arced along the top of the ring annulus.
            # Phil Noy gave away this method for free; this credit honors him.
            # Replaces the previous size-range label (which was redundant with
            # the variant name shown in the UI). Uses the same engraving
            # mode (filled/line) as the size labels so the visual style is
            # consistent across all the engraved text on the part.
            tooling = settings.get("tooling_settings", {})
            font_size = tooling.get("ring_font_size", 3.5)
            ring_width = HOLDER_OUTER_R - inner_r
            if font_size > ring_width * 0.9:
                font_size = ring_width * 0.9
            ring_center_r = (HOLDER_OUTER_R + inner_r) / 2

            # Engraving speed/power: match the user's engraving_mode.
            if engraving_mode == "filled":
                eng_speed = mat_settings.get("filled_engraving_speed", 800)
                eng_power = mat_settings.get("filled_engraving_power", 15)
                eng_passes = mat_settings.get("filled_engraving_passes", 1)
                filled_line_spacing = mat_settings.get("filled_line_spacing", 0.15)
                credit_strokes = get_filled_text_strokes_arc(
                    "DESIGNED BY PHIL NOY", font_size,
                    cx, cy, ring_center_r, math.pi / 2.0,
                    filled_line_spacing, side='top')
            else:
                eng_speed = mat_settings.get("engraving_speed", 800)
                eng_power = mat_settings.get("engraving_power", 15)
                eng_passes = mat_settings.get("engraving_passes", 1)
                credit_strokes = get_text_strokes_arc(
                    "DESIGNED BY PHIL NOY", font_size,
                    cx, cy, ring_center_r, math.pi / 2.0, side='top')
            engraving_strokes.extend(credit_strokes)

    # Bounds
    all_x = [0, width_mm]
    all_y = [0, height_mm]

    gcode_lines = []
    gcode_lines.extend(generate_gcode_header(min(all_x), min(all_y), max(all_x), max(all_y)))

    # Engrave ring labels first (if any)
    if engraving_strokes:
        air_assist_eng = mat_settings.get("air_assist_engraving", True)
        overscan_mm = 0
        if engraving_mode == "filled" and settings.get("filled_overscan_enabled", False):
            overscan_mm = settings.get("filled_overscan_mm", 1.5)
        gcode_lines.extend(generate_gcode_layer(engraving_strokes, eng_speed, eng_power, 'C03',
                                                 overscan_mm=overscan_mm, air_assist=air_assist_eng,
                                                 passes=eng_passes))

    if hole_strokes:
        gcode_lines.extend(generate_gcode_layer(hole_strokes, hole_speed, hole_power, 'C01',
                                                 air_assist=air_assist_hole, passes=hole_passes))
    if inner_cut_strokes:
        gcode_lines.extend(generate_gcode_layer(inner_cut_strokes, cut_speed, cut_power, 'C02',
                                                 air_assist=air_assist_cut, passes=cut_passes))
    if outer_cut_strokes:
        gcode_lines.extend(generate_gcode_layer(outer_cut_strokes, cut_speed, cut_power, 'C00',
                                                 air_assist=air_assist_cut, passes=cut_passes))

    gcode_lines.extend(generate_gcode_footer(return_speed=return_speed))

    with open(filename, 'w') as f:
        f.write('\n'.join(gcode_lines))


# ==========================================
# KERF TEST G-CODE GENERATION
# ==========================================

def generate_kerf_test_gcode(material_name, filename, settings, cut_speed, cut_power,
                              eng_speed, eng_power, engraving_mode="line",
                              filled_line_spacing=0.15):
    """
    Generate G-code for a kerf test pattern: 3 circles at known diameters
    with engraved labels and instructions. No kerf compensation applied.
    """
    from svg_engine import KERF_TEST_DIAMETERS

    spacing = 5.0
    max_r = max(KERF_TEST_DIAMETERS) / 2
    title_height = 8.0
    label_height = 6.0
    instruction_height = 12.0

    positions = []
    x_cursor = spacing
    for dia in KERF_TEST_DIAMETERS:
        r = dia / 2
        cx = x_cursor + max_r
        positions.append((dia, cx, r))
        x_cursor += max_r * 2 + spacing

    width_mm = x_cursor
    svg_cy = title_height + label_height + max_r + spacing
    height_mm = svg_cy + max_r + spacing + instruction_height

    # Flip Y for G-code
    cy = height_mm - svg_cy

    return_speed = settings.get("gcode_return_speed", 1000)

    overscan_mm = 0
    if engraving_mode == "filled" and settings.get("filled_overscan_enabled", False):
        overscan_mm = settings.get("filled_overscan_mm", 1.5)

    # Engraving strokes
    engraving_strokes = []

    # Title
    title_text = f"Kerf Test - {material_name}"
    title_y_svg = title_height * 0.7
    title_y = height_mm - title_y_svg
    if engraving_mode == "filled":
        engraving_strokes.extend(get_filled_text_strokes(title_text, 4.0, width_mm / 2, title_y, filled_line_spacing))
    else:
        engraving_strokes.extend(get_text_strokes(title_text, 4.0, width_mm / 2, title_y))

    # Labels
    for dia, cx, r in positions:
        label_text = f"{dia:.0f}"
        label_y_svg = title_height + label_height * 0.5
        label_y = height_mm - label_y_svg
        if engraving_mode == "filled":
            engraving_strokes.extend(get_filled_text_strokes(label_text, 3.5, cx, label_y, filled_line_spacing))
        else:
            engraving_strokes.extend(get_text_strokes(label_text, 3.5, cx, label_y))

    height_mm = svg_cy + max_r + spacing
    cy = height_mm - svg_cy  # Recompute with final height

    # Cut strokes - NO kerf compensation
    cut_strokes = []
    for dia, cx, r in positions:
        cut_strokes.append(linearize_circle(cx, cy, r, segments=72))

    # Build G-code
    gcode_lines = []
    gcode_lines.extend(generate_gcode_header(0, 0, width_mm, height_mm))

    if engraving_strokes:
        gcode_lines.extend(generate_gcode_layer(engraving_strokes, eng_speed, eng_power, 'C03',
                                                 overscan_mm=overscan_mm, air_assist=True))
    if cut_strokes:
        gcode_lines.extend(generate_gcode_layer(cut_strokes, cut_speed, cut_power, 'C02',
                                                 air_assist=True))

    gcode_lines.extend(generate_gcode_footer(return_speed=return_speed))

    with open(filename, 'w') as f:
        f.write('\n'.join(gcode_lines))


def generate_calibration_card_gcode(filename, cols=8, rows=6,
                                     square_mm=25.0, marker_mm=18.0,
                                     border_mm=10.0,
                                     engrave_speed=6000, engrave_power=25,
                                     engrave_passes=1, line_spacing_mm=0.15,
                                     settings=None, air_assist=True):
    """Generate G-code engraving the ChArUco camera-calibration card.

    The card is rendered at a DPI matched to line_spacing_mm and raster-
    engraved as horizontal scan lines. Single layer, no cut path — the
    basswood stays whole and just gets the pattern burned in.

    Defaults (6000 mm/min, 25%, single pass) are tuned for basswood on
    a Creality Falcon2 Pro 40W; user can override in the Tooling-tab UI.
    """
    from camera_capture import make_calibration_card_strokes

    settings = settings or {}
    return_speed = settings.get("gcode_return_speed", 1000)
    overscan_mm = 0
    if settings.get("filled_overscan_enabled", False):
        overscan_mm = settings.get("filled_overscan_mm", 1.5)

    # Build the strokes with the pattern offset by `border_mm` from the
    # G-code origin (which sits at the bottom-left of the sheet).
    strokes_y_down = make_calibration_card_strokes(
        cols, rows, square_mm, marker_mm,
        line_spacing_mm=line_spacing_mm,
        origin_x_mm=border_mm, origin_y_mm=border_mm,
    )

    sheet_w = cols * square_mm + 2 * border_mm
    sheet_h = rows * square_mm + 2 * border_mm

    # camera_capture returns strokes in SVG Y-down coords (row 0 at top).
    # G-code uses Y-up with origin at bottom-left, so flip every Y.
    strokes_y_up = [
        [(x, sheet_h - y) for (x, y) in stroke]
        for stroke in strokes_y_down
    ]

    lines = []
    lines.extend(generate_gcode_header(0, 0, sheet_w, sheet_h))
    lines.extend(generate_gcode_layer(
        strokes_y_up, engrave_speed, engrave_power, 'CAL',
        overscan_mm=overscan_mm, air_assist=air_assist,
        passes=engrave_passes,
    ))
    lines.extend(generate_gcode_footer(return_speed=return_speed))

    with open(filename, 'w') as f:
        f.write('\n'.join(lines))


def generate_feeds_speeds_test_gcode(test_pieces, sheet_w_mm, sheet_h_mm, filename,
                                     settings, air_assist=True,
                                     eng_speed_override=None,
                                     eng_power_override=None):
    """
    Generate G-code for a feeds & speeds test sheet.

    Emits, in order:
      1. ONE engraving layer containing all disc labels at the engraving
         speed/power passed via overrides (or the selected material's
         defaults if overrides are None). The whole point of the tool is
         that the user may not have dialed in their cut settings yet, so
         they need explicit control over the engraving feed/power too —
         otherwise the labels might come out illegible and they'd be unable
         to identify which disc had which parameters.
      2. ONE cut layer per disc, named `C{id}`, with each layer's S/F/passes
         set from that piece's own (speed, power, passes) triple. Distinct
         layer names keep LightBurn import from collapsing them.

    test_pieces: list of dicts with keys 'id' (str like "01"), 'cx', 'cy',
                 'diameter' (mm, SVG Y-down coords), 'speed' (mm/min),
                 'power' (%), 'passes' (int). Optional 'engraving_on'
                 (default True), 'material' (defaults to 'felt').

    eng_speed_override, eng_power_override: when not None, override the
    material's engraving defaults for the label engraving layer.
    """
    return_speed = settings.get("gcode_return_speed", 1000)

    material_key = test_pieces[0].get('material', 'felt') if test_pieces else 'felt'
    mat_settings = settings.get("gcode_settings", {}).get(material_key, {})
    engraving_mode = mat_settings.get("engraving_mode", "line")
    filled_spacing = mat_settings.get("filled_line_spacing", 0.15)
    if engraving_mode == "filled":
        eng_speed = mat_settings.get("filled_engraving_speed", 1000)
        eng_power = mat_settings.get("filled_engraving_power", 15)
        eng_passes = mat_settings.get("filled_engraving_passes", 1)
    else:
        eng_speed = mat_settings.get("engraving_speed", 1000)
        eng_power = mat_settings.get("engraving_power", 15)
        eng_passes = mat_settings.get("engraving_passes", 1)
    if eng_speed_override is not None:
        eng_speed = eng_speed_override
    if eng_power_override is not None:
        eng_power = eng_power_override

    overscan_mm = 0
    if engraving_mode == "filled" and settings.get("filled_overscan_enabled", False):
        overscan_mm = settings.get("filled_overscan_mm", 1.5)

    # Collect engraving strokes for ALL labels (Y-flipped to G-code coords)
    engraving_strokes = []
    for piece in test_pieces:
        if not piece.get('engraving_on', True):
            continue
        label = piece['id']
        font_size = max(min(piece['diameter'] * 0.3, 5.0), 2.5)
        cy_gcode = sheet_h_mm - piece['cy']
        if engraving_mode == "filled":
            engraving_strokes.extend(
                get_filled_text_strokes(label, font_size, piece['cx'], cy_gcode, filled_spacing))
        else:
            engraving_strokes.extend(
                get_text_strokes(label, font_size, piece['cx'], cy_gcode))

    gcode_lines = []
    gcode_lines.extend(generate_gcode_header(0, 0, sheet_w_mm, sheet_h_mm))

    if engraving_strokes:
        gcode_lines.extend(generate_gcode_layer(
            engraving_strokes, eng_speed, eng_power, 'C00',
            overscan_mm=overscan_mm, air_assist=air_assist, passes=eng_passes))

    # Per-piece cut layers. air_assist defaults to the global parameter
    # but each piece can override (used when "Also test with air off" is
    # enabled so half the matrix runs without air for comparison).
    for piece in test_pieces:
        cy_gcode = sheet_h_mm - piece['cy']
        cut_strokes = [linearize_circle(piece['cx'], cy_gcode, piece['diameter'] / 2.0,
                                        segments=72)]
        layer_name = f"C{piece['id']}"
        piece_air = piece.get('air_assist', air_assist)
        gcode_lines.extend(generate_gcode_layer(
            cut_strokes, piece['speed'], piece['power'], layer_name,
            air_assist=piece_air, passes=piece['passes']))

    gcode_lines.extend(generate_gcode_footer(return_speed=return_speed))

    with open(filename, 'w') as f:
        f.write('\n'.join(gcode_lines))


